<?php
use App\Http\Controllers\Api\V1\{FieldWorkforceController,MobileFieldController};use App\Http\Middleware\ResolveWorkspace;use Illuminate\Support\Facades\Route;
Route::prefix('v1')->group(function(){
 Route::post('/mobile/login',[MobileFieldController::class,'login'])->middleware('throttle:10,1');
 Route::middleware(['mobile.auth','workspace.module:field','throttle:240,1'])->prefix('mobile')->group(function(){Route::post('/logout',[MobileFieldController::class,'logout']);Route::post('/push-token',[MobileFieldController::class,'pushToken']);Route::get('/bootstrap',[MobileFieldController::class,'bootstrap']);Route::get('/work-orders',[MobileFieldController::class,'orders']);Route::get('/work-orders/{order}',[MobileFieldController::class,'showOrder']);Route::patch('/work-orders/{order}/status',[MobileFieldController::class,'updateOrderStatus']);Route::post('/work-orders/{order}/files',[MobileFieldController::class,'uploadFile']);Route::post('/checkpoints/scan',[MobileFieldController::class,'scan']);Route::post('/forms/{template}/submit',[MobileFieldController::class,'submitForm']);Route::post('/incidents',[MobileFieldController::class,'incident']);Route::post('/sync',[MobileFieldController::class,'sync']);});
 Route::middleware(['auth:sanctum',ResolveWorkspace::class,'workspace.abac:field,*'])->prefix('field')->group(function(){Route::get('/overview',[FieldWorkforceController::class,'overview'])->middleware('workspace.permission_any:field.view_own,field.view_team,field.manage');Route::post('/work-orders',[FieldWorkforceController::class,'storeOrder'])->middleware('workspace.permission:field.manage');Route::patch('/work-orders/{order}',[FieldWorkforceController::class,'updateOrder'])->middleware('workspace.permission:field.manage');Route::post('/checkpoints',[FieldWorkforceController::class,'storeCheckpoint'])->middleware('workspace.permission:field.manage');Route::post('/forms',[FieldWorkforceController::class,'storeForm'])->middleware('workspace.permission:field.forms.manage');Route::patch('/incidents/{incident}',[FieldWorkforceController::class,'reviewIncident'])->middleware('workspace.permission:field.incidents.manage');Route::get('/files/{file}/download',[FieldWorkforceController::class,'downloadFile'])->middleware('workspace.permission_any:field.view_own,field.view_team,field.manage');});
});
